function smallestDistancePair(nums, k) {
  const a = [...nums].sort((x, y) => x - y);
  const countWithin = (d) => {                   // how many pairs are at most d apart?
    let count = 0, left = 0;
    for (let right = 0; right < a.length; right++) {
      while (a[right] - a[left] > d) left++;     // shrink until the window spans at most d
      count += right - left;                     // a[right] pairs with every value in the window
    }
    return count;
  };
  let low = 0;
  let high = a[a.length - 1] - a[0];
  while (low < high) {
    const mid = low + Math.floor((high - low) / 2);
    if (countWithin(mid) >= k) high = mid;       // at least k pairs within mid: the answer is mid or less
    else low = mid + 1;                          // fewer than k: the answer is bigger
  }
  return low;
}

def smallest_distance_pair(nums, k):
    a = sorted(nums)
    def count_within(d):                  # how many pairs are at most d apart?
        count = left = 0
        for right in range(len(a)):
            while a[right] - a[left] > d:
                left += 1                 # shrink until the window spans at most d
            count += right - left         # a[right] pairs with every value in the window
        return count
    low, high = 0, a[-1] - a[0]
    while low < high:
        mid = (low + high) // 2
        if count_within(mid) >= k:
            high = mid                    # at least k pairs within mid: the answer is mid or less
