    return low

int smallestDistancePair(int[] nums, int k) {
    int[] a = nums.clone();
    Arrays.sort(a);
    int low = 0, high = a[a.length - 1] - a[0];
    while (low < high) {
        int mid = low + (high - low) / 2;
        if (countWithin(a, mid) >= k) high = mid;   // at least k pairs within mid: mid or less
        else low = mid + 1;                         // fewer than k: the answer is bigger
    }
    return low;
}

long countWithin(int[] a, int d) {               // how many pairs are at most d apart?
    long count = 0;
    int left = 0;
    for (int right = 0; right < a.length; right++) {
        while (a[right] - a[left] > d) left++;   // shrink until the window spans at most d
        count += right - left;                   // a[right] pairs with every value in the window
    }
    return count;
}

long long countWithin(vector<int>& a, int d) {   // how many pairs are at most d apart?
